const raw = $json.output ?? $json;

let parsed = raw;

if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      `La respuesta de IA no es JSON válido: ${error.message}`
    );
  }
}

// Algunas versiones pueden envolver nuevamente el resultado en "output".
if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.output &&
  typeof parsed.output === 'object'
) {
  parsed = parsed.output;
}

if (
  !parsed ||
  typeof parsed.assistant_message !== 'string' ||
  !parsed.assistant_message.trim()
) {
  throw new Error(
    `No se encontró assistant_message. Datos recibidos: ${JSON.stringify(parsed)}`
  );
}

return [
  {
    json: {
      session_id: $('Chat Trigger').first().json.sessionId ?? '',
      created_at: new Date().toISOString(),
      user_message: $('Chat Trigger').first().json.chatInput ?? '',
      assistant_message: parsed.assistant_message.trim(),
      profile_update_json: JSON.stringify(parsed.profile_update ?? {}),
      section_updated: parsed.section_updated ?? '',
      completion_percentage:
        parsed.profile_completion_percentage ?? 0,
      missing_sections_json: JSON.stringify(
        parsed.missing_sections ?? []
      ),
      interview_complete: parsed.interview_complete ?? false
    }
  }
];

const record = $('Prepare Storage Record').first().json;

if (
  !record.assistant_message ||
  typeof record.assistant_message !== 'string'
) {
  throw new Error(
    `assistant_message no está disponible. Datos recibidos: ${JSON.stringify(record)}`
  );
}

return [
  {
    json: {
      output: record.assistant_message
    }
  }
];

const chat = $('Chat Trigger').first().json;

const rows = $input.all()
  .map(item => item.json)
  .filter(row => {
    const profile = row.cv_profile_json;
    const status = String(row.status ?? '').trim();
    return profile && (!status || status === 'ready_for_interview');
  });

rows.sort((a, b) => {
  const dateA = new Date(a.uploaded_at ?? 0).getTime();
  const dateB = new Date(b.uploaded_at ?? 0).getTime();
  return dateB - dateA;
});

const candidate = rows[0] ?? null;

return [{
  json: {
    chatInput: chat.chatInput ?? '',
    sessionId: chat.sessionId ?? '',
    has_cv: Boolean(candidate),
    candidate_id: candidate?.candidate_id ?? '',
    candidate_name: candidate?.full_name ?? '',
    candidate_email: candidate?.email ?? '',
    cv_profile_json: candidate?.cv_profile_json ?? '{}'
  }
}];

let cvProfile = {};

if ($json.has_cv) {
  try {
    cvProfile =
      typeof $json.cv_profile_json === 'string'
        ? JSON.parse($json.cv_profile_json)
        : ($json.cv_profile_json ?? {});
  } catch (error) {
    cvProfile = {};
  }
}

const contextInstructions = $json.has_cv
  ? `
HAS_CV: true

The person uploaded a CV. Use the following information as preliminary context:

${JSON.stringify(cvProfile, null, 2)}

Do not repeat questions whose answers are already clearly present.
Deepen personal contribution, difficult situations, decisions, tools,
measurable impact, improvements, collaboration and achievements.
`
  : `
HAS_CV: false

The person did not upload a CV, or no usable CV context was found.
Build the profile from scratch. Start with the current or most recent
professional role and continue one question at a time.
`;

return [{
  json: {
    ...$json,
    agent_input: `
CURRENT USER MESSAGE:
${$json.chatInput}

${contextInstructions}

Directly confirmed information from the user has priority over the CV.
Never mention JSON, Google Sheets, nodes, workflows or internal processing.
Respond in Spanish and ask no more than one primary question.
`.trim()
  }
}];
